require "rails_helper"

RSpec.describe Timekeeping::FinancialSnapshot do
  # "Every check is keyed by `company_id`. No report or result mixes companies."
  # Comparing two companies would list every row of both as added or removed,
  # carrying one tenant's money values under the other's company_id.
  it "refuses to compare snapshots of two different companies instead of returning a mixed difference list" do
    company_a = create(:company)
    company_b = create(:company)
    create(:invoice, company: company_a)
    create(:invoice, company: company_b)

    snapshot_a = described_class.take(company_id: company_a.id)
    snapshot_b = described_class.take(company_id: company_b.id)

    expect { described_class.compare(snapshot_a, snapshot_b) }.to raise_error(ArgumentError)
  end
end

RSpec.describe Timekeeping::FinancialSnapshot do
  # A wrong company id must not yield an empty snapshot: two empty snapshots
  # compare as identical, which would prove "Two snapshots with no change
  # between them compare as identical" over no money at all.
  it "raises for a company id that does not exist rather than returning an empty snapshot that compares as identical" do
    missing_company_id = (Company.maximum(:id) || 0) + 1_000

    expect { described_class.take(company_id: missing_company_id) }
      .to raise_error(ActiveRecord::RecordNotFound)
  end
end

RSpec.describe Timekeeping::FinancialSnapshot do
  # "A mutated invoice, line item, invoice tax or PDF total value makes the
  # comparison fail and names the changed value". A comparison that only walks
  # the keys of the after snapshot would miss a row that vanished.
  it "reports a line item deleted between snapshots with its old rate and quantity and a nil new value" do
    company = create(:company)
    invoice = create(:invoice_with_invoice_line_items, company:, length: 2)
    removed_item = invoice.invoice_line_items.order(:id).first
    old_rate = removed_item.rate
    old_quantity = removed_item.quantity

    before_snapshot = described_class.take(company_id: company.id)
    removed_item.delete
    after_snapshot = described_class.take(company_id: company.id)

    differences = described_class.compare(before_snapshot, after_snapshot)
    removed = differences.select { |d| d.kind == :line_item && d.record_id == removed_item.id }

    expect(removed.map(&:field)).to include(:rate, :quantity)
    expect(removed.find { |d| d.field == :rate }).to have_attributes(old_value: old_rate, new_value: nil, company_id: company.id)
    expect(removed.find { |d| d.field == :quantity }).to have_attributes(old_value: old_quantity, new_value: nil, company_id: company.id)
  end
end

RSpec.describe Timekeeping::FinancialSnapshot do
  # "every `invoice_taxes` row" is part of the money check, so a row that
  # appears after the first snapshot is a change, not something to skip
  # because the before snapshot has no key for it.
  it "reports an invoice tax row added between snapshots with a nil old value" do
    company = create(:company)
    invoice = create(:invoice_with_invoice_line_items, company:, length: 1)

    before_snapshot = described_class.take(company_id: company.id)
    added_tax = create(:invoice_tax, invoice:)
    after_snapshot = described_class.take(company_id: company.id)

    differences = described_class.compare(before_snapshot, after_snapshot)
    added_amount = differences.find { |d| d.kind == :invoice_tax && d.record_id == added_tax.id && d.field.to_s == "amount" }

    expect(added_amount).to be_present
    expect(added_amount).to have_attributes(old_value: nil, company_id: company.id)
    expect(added_amount.new_value).to eq(added_tax.reload.amount)
  end
end

RSpec.describe Timekeeping::FinancialSnapshot do
  # "Include discarded invoices, so a change to any invoice row is caught."
  # Discarding between two snapshots must not make the invoice's values look
  # deleted, and a later change to the discarded row must still be reported.
  it "keeps an invoice discarded between snapshots and reports a money change made after the discard" do
    company = create(:company)
    invoice = create(:invoice_with_invoice_line_items, company:, length: 1)

    before_snapshot = described_class.take(company_id: company.id)
    invoice.discard!
    invoice.update_column(:outstanding_amount, invoice.reload.outstanding_amount + BigDecimal("10.00"))
    after_snapshot = described_class.take(company_id: company.id)

    differences = described_class.compare(before_snapshot, after_snapshot)
    invoice_differences = differences.select { |d| d.kind == :invoice && d.record_id == invoice.id }

    expect(invoice_differences.map(&:field)).to eq([:outstanding_amount])
    expect(invoice_differences.first).to have_attributes(
      company_id: company.id,
      old_value: invoice.outstanding_amount - BigDecimal("10.00"),
      new_value: invoice.outstanding_amount
    )
  end
end

RSpec.describe Timekeeping::FinancialSnapshot do
  # "A snapshot of one company never contains another company's invoices."
  # If the snapshot query dropped its company scope, a change in company B
  # would surface as a difference in company A's comparison.
  it "reports no difference for one company when only another company's invoice money changed" do
    company_a = create(:company)
    company_b = create(:company)
    create(:invoice_with_invoice_line_items, company: company_a, length: 1)
    invoice_b = create(:invoice_with_invoice_line_items, company: company_b, length: 1)

    before_a = described_class.take(company_id: company_a.id)
    before_b = described_class.take(company_id: company_b.id)
    invoice_b.update_column(:discount, invoice_b.reload.discount + BigDecimal("10.00"))
    after_a = described_class.take(company_id: company_a.id)
    after_b = described_class.take(company_id: company_b.id)

    expect(described_class.compare(before_a, after_a)).to eq([])
    differences_b = described_class.compare(before_b, after_b)
    expect(differences_b).not_to be_empty
    expect(differences_b.map(&:company_id).uniq).to eq([company_b.id])
  end
end

RSpec.describe Timekeeping::FinancialSnapshot, :two_tenant_seed do
  it "emits one signal per difference with each difference's own company_id when one list holds two companies' changes" do
    fork_invoice = fork_and_leaf.invoices.order(:id).first
    copper_invoice = copper_kettle.invoices.order(:id).first

    fork_before = described_class.take(company_id: fork_and_leaf.id)
    copper_before = described_class.take(company_id: copper_kettle.id)
    fork_invoice.update_column(:outstanding_amount, fork_invoice.outstanding_amount.to_d + 10)
    copper_invoice.update_column(:outstanding_amount, copper_invoice.outstanding_amount.to_d + 10)

    differences =
      described_class.compare(fork_before, described_class.take(company_id: fork_and_leaf.id)) +
      described_class.compare(copper_before, described_class.take(company_id: copper_kettle.id))
    expect(differences.map(&:company_id)).to contain_exactly(fork_and_leaf.id, copper_kettle.id)

    recorded = []
    recorder = Object.new
    recorder.define_singleton_method(:emit) { |event| recorded << event }
    Rails.event.subscribe(recorder)
    begin
      returned = described_class.report(differences)
    ensure
      Rails.event.unsubscribe(recorder)
    end

    # "Each difference is emitted as a signal carrying `company_id` through `Rails.event.notify`, following `app/events/users/signed_in.rb`."
    signals = recorded.select { |event| event[:name] == "Timekeeping::FinancialSnapshotChanged" }
    expect(returned).to eq(differences)
    expect(signals.size).to eq(differences.size)
    signal_data = signals.map { |event| event[:payload].to_h[:data] }
    expect(signal_data).to contain_exactly(
      { company_id: fork_and_leaf.id, kind: :invoice, record_id: fork_invoice.id, field: :outstanding_amount },
      { company_id: copper_kettle.id, kind: :invoice, record_id: copper_invoice.id, field: :outstanding_amount }
    )
  end
end

RSpec.describe Timekeeping::FinancialSnapshot, :two_tenant_seed do
  it "stores a financial snapshot signal per difference without the old or new money values in its payload" do
    invoice = fork_and_leaf.invoices.order(:id).first
    before_snapshot = described_class.take(company_id: fork_and_leaf.id)
    invoice.update_column(:tax, invoice.tax.to_d + 10)
    differences = described_class.compare(before_snapshot, described_class.take(company_id: fork_and_leaf.id))
    expect(differences).not_to be_empty

    # "Each snapshot difference is emitted as a signal carrying company_id"
    event = assert_event_reported("Timekeeping::FinancialSnapshotChanged") do
      described_class.report(differences)
    end
    data = event[:payload].to_h[:data]
    expect(data[:company_id]).to eq(fork_and_leaf.id)
    expect(data.keys).to contain_exactly(:company_id, :kind, :record_id, :field)
    expect(RailsEventViewer::Entry.where(name: "Timekeeping::FinancialSnapshotChanged").count).to eq(differences.size)
  end
end

RSpec.describe Timekeeping::FinancialSnapshot, :two_tenant_seed do
  it "takes a snapshot of an invoice whose stored amount disagrees with its line items without writing any billing table" do
    invoice = fork_and_leaf.invoices.joins(:invoice_line_items).order(:id).first
    # A stale stored amount is what a totals-sync callback would rewrite if the snapshot saved anything.
    invoice.update_columns(amount: invoice.amount.to_d + 123, outstanding_amount: invoice.outstanding_amount.to_d + 123)
    stored_before = invoice.reload.attributes

    billing_writes = []
    callback = lambda do |*, payload|
      sql = payload[:sql].to_s
      if sql.match?(/\A\s*(INSERT|UPDATE|DELETE)/i) && sql.match?(/"(invoices|invoice_line_items|invoice_taxes)"/)
        billing_writes << sql
      end
    end
    ActiveSupport::Notifications.subscribed(callback, "sql.active_record") do
      described_class.take(company_id: fork_and_leaf.id)
    end

    # "Taking a snapshot writes no billing table, and the rendered PDF output is unchanged"
    expect(billing_writes).to be_empty
    expect(invoice.reload.attributes).to eq(stored_before)
  end
end
